/** 
 * Initiates service  {@linkplain Service#start startup} on all the services being managed.  It isonly valid to call this method if all of the services are  {@linkplain State#NEW new}.
 * @return this
 * @throws IllegalStateException if any of the Services are not {@link State#NEW new} when the method is called.
 */
public ServiceManager startAsync(){
  for (  Map.Entry<Service,ServiceListener> entry : services.entrySet()) {
    Service service=entry.getKey();
    State state=service.state();
    checkState(state == State.NEW,"Service %s is %s, cannot start it.",service,state);
  }
  for (  ServiceListener service : services.values()) {
    try {
      service.start();
    } catch (RuntimeException e) {
      throw new IllegalStateException("Failed to start service", e);
    }
  }
  return this;
}
